package com.axiom.analysis.correlation; import com.axiom.domain.pipeline.FileCategory;import java.util.*;import org.springframework.stereotype.Service;
@Service public class ChangeRelevanceService {public Result analyze(String failureCategory,Collection<FileCategory> files,boolean predates,boolean rerunPassed){double score=0;if(predates)score-=.7;if(rerunPassed)score-=.6;if(files.size()>0&&files.stream().allMatch(f->f==FileCategory.DOCUMENTATION))score-=.8;if(failureCategory.equals("DEPENDENCY_FAILURE")&&files.stream().anyMatch(f->f==FileCategory.DEPENDENCY_MANIFEST||f==FileCategory.DEPENDENCY_LOCKFILE))score+=.9;if((failureCategory.equals("INFRASTRUCTURE_FAILURE")||failureCategory.equals("CONFIGURATION_FAILURE"))&&files.stream().anyMatch(f->f==FileCategory.CI_CONFIGURATION||f==FileCategory.INFRASTRUCTURE_CONFIGURATION||f==FileCategory.APPLICATION_CONFIGURATION))score+=.8;String r=score>=.8?"RELATED":score>=.55?"LIKELY_RELATED":score<=-.7?"UNRELATED":score<=-.35?"UNLIKELY_RELATED":"INDETERMINATE";return new Result(r,Math.min(1,Math.abs(score)),"change-relevance-v1");}public record Result(String relevance,double confidence,String version){}}
